<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Можно ли уступить право требования оплаты по госконтракту?", "acceptedAnswer": {"@type": "Answer", "text": "Да. Верховный Суд подтвердил, что уступка денежного требования по контракту 44-ФЗ закону не противоречит: запрет ч. 5 ст. 95 касается перемены исполнителя, а не долга за принятое исполнение. Минфин в письме от 14.12.2023 № 02-17-09/121366 с этим согласился."}}, {"@type": "Question", "name": "Нужно ли согласие заказчика на цессию?", "acceptedAnswer": {"@type": "Answer", "text": "Формально — нет: уступка денежного требования действительна и без согласия должника, даже при договорном запрете (п. 3 ст. 388 ГК). Практически при казначейском сопровождении без заказчика не обойтись: нужно дополнительное соглашение о реквизитах нового получателя, иначе платёж не пройдёт санкционирование."}}, {"@type": "Question", "name": "Почему казначейство вернуло платёж в адрес цессионария?", "acceptedAnswer": {"@type": "Answer", "text": "ТОФК при санкционировании сверяет наименование, ИНН, КПП и банковские реквизиты получателя в распоряжении с реквизитами, указанными в контракте (подп. «е» п. 24 Порядка № 214н). Пока получателем в контракте числится исполнитель, платёж любому другому лицу возвращается без исполнения."}}, {"@type": "Question", "name": "Действует ли запрет уступки, прописанный в контракте?", "acceptedAnswer": {"@type": "Answer", "text": "Для денежного требования — нет: п. 3 ст. 388 ГК сохраняет силу уступки даже при договорном запрете. Цедент лишь несёт ответственность перед должником за нарушение такого условия, если она предусмотрена."}}, {"@type": "Question", "name": "Чем цессия отличается от перемены поставщика?", "acceptedAnswer": {"@type": "Answer", "text": "Цессия передаёт только долг заказчика за исполненное — исполнителем контракта остаётся прежняя компания со всеми обязанностями. Перемена поставщика заменяет сторону контракта целиком и допускается лишь при правопреемстве из-за реорганизации (ч. 5 ст. 95 Закона № 44-ФЗ)."}}, {"@type": "Question", "name": "Работает ли факторинг по контрактам с казначейским сопровождением?", "acceptedAnswer": {"@type": "Answer", "text": "Да, при правильном оформлении: Порядок № 214н прямо предусматривает коды для таких расчётов — 0632 для перечислений фактору и 0633 для поступлений от него. Условие то же, что и для цессии: получатель платежа должен появиться в контракте через дополнительное соглашение."}}, {"@type": "Question", "name": "Можно ли уступить будущие платежи по контракту?", "acceptedAnswer": {"@type": "Answer", "text": "Гражданский кодекс допускает уступку будущего требования в рамках факторинга (ст. 826 ГК). Практически фактор финансирует под подтверждённую приёмку: требование за неисполненный этап спорно и обременено рисками недостатков, неустоек и удержаний."}}, {"@type": "Question", "name": "Возможна ли цессия по гособоронзаказу?", "acceptedAnswer": {"@type": "Answer", "text": "С отдельного счёта — фактически нет: режим ст. 8.3–8.4 Закона № 275-ФЗ допускает расчёты только в рамках кооперации, и платёж стороннему цессионарию уполномоченный банк не проведёт. Уступка возможна лишь по средствам, законно выведенным из режима после исполнения контракта."}}, {"@type": "Question", "name": "Что делать, если заказчик отказывается платить цессионарию по контракту без казначейского сопровождения?", "acceptedAnswer": {"@type": "Answer", "text": "После получения уведомления об уступке платёж прежнему кредитору перестаёт быть надлежащим исполнением. Отказ платить новому кредитору оспаривается в суде — практика по денежным требованиям на стороне цессионария."}}, {"@type": "Question", "name": "Уведомлять ли казначейство об уступке?", "acceptedAnswer": {"@type": "Answer", "text": "Специальной процедуры уведомления ТОФК нет. Казначейство работает с документами: изменённые реквизиты получателя должны появиться в контракте и в реестре контрактов — тогда сверка при санкционировании пройдёт."}}, {"@type": "Question", "name": "Как учитывается дисконт при уступке?", "acceptedAnswer": {"@type": "Answer", "text": "Убыток от уступки права требования учитывается по ст. 279 НК РФ, порядок зависит от того, уступлен долг до или после срока платежа. Выручка по контракту при этом признаётся в обычном порядке — уступка её не отменяет."}}, {"@type": "Question", "name": "Уступка помогает, если заказчик просто не платит?", "acceptedAnswer": {"@type": "Answer", "text": "Это разные инструменты. Если долг просрочен и заказчик не платит, работают претензия, неустойка и взыскание через суд с последующим предъявлением исполнительного листа в казначейство. Уступка — способ получить деньги раньше срока, а не заставить должника платить."}}]}
</script>
